CREATE TYPE "UserAvatarSource" AS ENUM ('system', 'custom');

CREATE TABLE "SystemAvatar" (
  "id" VARCHAR(128) NOT NULL,
  "storageKey" VARCHAR(255) NOT NULL,
  "publicUrl" VARCHAR(512) NOT NULL,
  "mimeType" VARCHAR(64) NOT NULL DEFAULT 'image/webp',
  "sortOrder" INTEGER NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "SystemAvatar_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "SystemAvatar_storageKey_key" ON "SystemAvatar"("storageKey");
CREATE UNIQUE INDEX "SystemAvatar_publicUrl_key" ON "SystemAvatar"("publicUrl");
CREATE UNIQUE INDEX "SystemAvatar_sortOrder_key" ON "SystemAvatar"("sortOrder");

CREATE TABLE "UserAvatarAsset" (
  "id" TEXT NOT NULL,
  "userId" TEXT NOT NULL,
  "storageKey" VARCHAR(255) NOT NULL,
  "publicUrl" VARCHAR(512) NOT NULL,
  "mimeType" VARCHAR(64) NOT NULL,
  "byteSize" INTEGER NOT NULL,
  "status" VARCHAR(24) NOT NULL,
  "deletePending" BOOLEAN NOT NULL DEFAULT false,
  "deletedAt" TIMESTAMP(3),
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "UserAvatarAsset_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "UserAvatarAsset_storageKey_key" ON "UserAvatarAsset"("storageKey");
CREATE UNIQUE INDEX "UserAvatarAsset_publicUrl_key" ON "UserAvatarAsset"("publicUrl");
CREATE INDEX "UserAvatarAsset_userId_status_createdAt_idx" ON "UserAvatarAsset"("userId", "status", "createdAt");
CREATE INDEX "UserAvatarAsset_status_createdAt_idx" ON "UserAvatarAsset"("status", "createdAt");
CREATE INDEX "UserAvatarAsset_deletePending_updatedAt_idx" ON "UserAvatarAsset"("deletePending", "updatedAt");

ALTER TABLE "User"
  ADD COLUMN "avatarUrl" VARCHAR(512),
  ADD COLUMN "avatarSource" "UserAvatarSource",
  ADD COLUMN "systemAvatarId" VARCHAR(128),
  ADD COLUMN "customAvatarAssetId" TEXT;

CREATE UNIQUE INDEX "User_customAvatarAssetId_key" ON "User"("customAvatarAssetId");
CREATE INDEX "User_systemAvatarId_idx" ON "User"("systemAvatarId");

ALTER TABLE "UserAvatarAsset"
  ADD CONSTRAINT "UserAvatarAsset_userId_fkey"
  FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "User"
  ADD CONSTRAINT "User_systemAvatarId_fkey"
  FOREIGN KEY ("systemAvatarId") REFERENCES "SystemAvatar"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "User"
  ADD CONSTRAINT "User_customAvatarAssetId_fkey"
  FOREIGN KEY ("customAvatarAssetId") REFERENCES "UserAvatarAsset"("id") ON DELETE SET NULL ON UPDATE CASCADE;


-- Built-in system avatar catalog (512x512 WebP in Platform Media COS).

-- Existing users receive one stable random built-in avatar at migration time.
UPDATE "User" AS target
SET "avatarUrl" = picked."publicUrl",
    "avatarSource" = 'system',
    "systemAvatarId" = picked."avatarId",
    "customAvatarAssetId" = NULL
FROM (
  SELECT candidate."id" AS "userId", avatar."id" AS "avatarId", avatar."publicUrl"
  FROM "User" AS candidate
  CROSS JOIN LATERAL (
    SELECT "id", "publicUrl"
    FROM "SystemAvatar"
    ORDER BY random()
    LIMIT 1
  ) AS avatar
) AS picked
WHERE target."id" = picked."userId";
